### Python

```python
import sys
sys.setrecursionlimit(200000)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    left = [0] * (n + 1)
    right = [0] * (n + 1)
    indeg = [0] * (n + 1)

    for i in range(1, n + 1):
        l = int(next(it))
        r = int(next(it))
        left[i] = l
        right[i] = r
        if l != -1:
            indeg[l] += 1
        if r != -1:
            indeg[r] += 1

    # 寻找根节点（入度为0）
    root = 1
    for i in range(1, n + 1):
        if indeg[i] == 0:
            root = i
            break

    dp = [0] * (n + 1)

    def dfs(u):
        l = left[u]
        r = right[u]
        if l == -1 and r == -1:
            dp[u] = 1
            return
        if l != -1:
            dfs(l)
        if r != -1:
            dfs(r)
        if l != -1 and r != -1 and dp[l] == dp[r] and dp[l] != 0:
            dp[u] = dp[l] + 1
        else:
            dp[u] = 0

    dfs(root)

    ans = sum(1 for v in dp[1:] if v != 0)
    print(ans)

if __name__ == "__main__":
    solve()
```

